{
  "name": "opencode-qoder",
  "version": "0.2.1",
  "description": "Qoder provider plugin for opencode",
  "keywords": [
    "ai-sdk-provider",
    "opencode",
    "opencode-plugin",
    "qoder"
  ],
  "homepage": "https://github.com/Moorad/opencode-qoder#readme",
  "bugs": {
    "url": "https://github.com/Moorad/opencode-qoder/issues"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Moorad/opencode-qoder.git"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "devDependencies": {
    "@ai-sdk/provider": "3.0.8",
    "@opencode-ai/plugin": "1.17.13",
    "@types/node": "^24.0.0",
    "typescript": "^5.8.2",
    "vitest": "^4.1.9"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0"
  },
  "scripts": {
    "build": "rm -rf ./dist && tsc -p tsconfig.json",
    "check": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run src"
  }
}
